sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.newStatus = '';
    c.resolutionNotes = c.data.record ? c.data.record.resolution_notes : '';
    c.assignTo = c.data.record ? c.data.record.assigned_to_id : '';
    c.newComment = '';
    c.updating = false;
    c.successMsg = '';
    c.errorMsg = '';

    c.updateRecord = function() {
        if (!c.newStatus && !c.assignTo && !c.resolutionNotes) return;
        c.updating = true;
        c.successMsg = '';
        c.errorMsg = '';

        c.data.action = 'update_status';
        c.data.sys_id = c.data.record.sys_id;
        c.data.new_status = c.newStatus;
        c.data.resolution_notes = c.resolutionNotes;
        c.data.assigned_to = c.assignTo;

        c.server.update().then(function() {
            c.updating = false;
            if (c.data.updateResult && c.data.updateResult.success) {
                c.successMsg = c.data.updateResult.message;
                c.data.action = null;
                c.server.refresh();
            } else {
                c.errorMsg = (c.data.updateResult && c.data.updateResult.message) || 'Update failed.';
                c.data.action = null;
            }
        });
    };

    c.addComment = function() {
        if (!c.newComment || !c.newComment.trim()) return;
        c.updating = true;
        c.data.action = 'add_comment';
        c.data.sys_id = c.data.record.sys_id;
        c.data.comment = c.newComment;

        c.server.update().then(function() {
            c.updating = false;
            c.newComment = '';
            c.data.action = null;
            c.server.refresh();
        });
    };

    c.goBack = function() {
        if (window.history.length > 1) {
            window.history.back();
        } else {
            window.location.href = '?id=wei_landing';
        }
    };
};

sp_widget.css:
.exc-detail-widget {
  padding: 10px 0;
}

.detail-header {
  background-color: $brand-primary;
  color: #fff;
  padding: 20px;
  border-radius: 6px;
  margin-bottom: 20px;
}

.detail-title {
  margin: 5px 0 0 0;
  font-weight: 700;
  color: #fff;
}

.detail-subtitle {
  margin: 5px 0 0 0;
  opacity: 0.9;
  font-size: 16px;
  color: #fff;
}

.detail-header .label-lg {
  font-size: 13px;
  padding: 5px 12px;
  margin-left: 5px;
}

.detail-panel-heading {
  background-color: $brand-primary;
  color: #fff;
  border: none;
}

.detail-panel-heading .panel-title {
  font-weight: 600;
  color: #fff;
}

.ai-panel-heading {
  background-color: #8E44AD;
  color: #fff;
  border: none;
}

.ai-panel-heading .panel-title {
  font-weight: 600;
  color: #fff;
}

.action-panel-heading {
  background-color: #E67E22;
  color: #fff;
  border: none;
}

.action-panel-heading .panel-title {
  font-weight: 600;
  color: #fff;
}

.dl-horizontal-custom dt {
  font-weight: 600;
  color: #666;
  margin-bottom: 5px;
  font-size: 12px;
  text-transform: uppercase;
}

.dl-horizontal-custom dd {
  margin-bottom: 12px;
  margin-left: 0;
}

.detail-description {
  margin-top: 15px;
  padding-top: 15px;
  border-top: 1px solid #eee;
}

.comment-item {
  padding: 10px 0;
  border-bottom: 1px solid #f0f0f0;
}

.comment-item:last-child {
  border-bottom: none;
}

.comment-meta {
  margin-bottom: 5px;
}

.comment-body {
  color: #333;
}

sp_widget.script:
(function() {
    var tableName = 'x_1956908_wareho_0_exception';
    var userId = gs.getUserID();

    data.isSupervisor = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
    data.isTechnician = gs.hasRole('x_1956908_wareho_0.technician');
    data.isStaff = !data.isSupervisor && !data.isTechnician;
    data.canEdit = data.isSupervisor || data.isTechnician;
    data.canAssign = data.isSupervisor;

    data.record = null;
    data.error = null;
    data.statusOptions = [];
    data.updateResult = null;

    // Handle update actions
    if (input && input.action === 'update_status') {
        var ugr = new GlideRecord(tableName);
        if (ugr.get(input.sys_id)) {
            if (input.new_status) {
                ugr.setValue('status', input.new_status);
                if (input.new_status === 'resolved' || input.new_status === 'closed') {
                    var now = new GlideDateTime();
                    ugr.setValue('resolved_at', now.getValue());
                }
            }
            if (input.resolution_notes) {
                ugr.setValue('resolution_notes', input.resolution_notes);
            }
            if (input.assigned_to && data.canAssign) {
                ugr.setValue('assigned_to', input.assigned_to);
                if (ugr.getValue('status') === 'new') {
                    ugr.setValue('status', 'assigned');
                }
            }
            ugr.update();
            data.updateResult = { success: true, message: 'Record updated successfully.' };
        } else {
            data.updateResult = { success: false, message: 'Record not found.' };
            return;
        }
    }

    if (input && input.action === 'add_comment') {
        var cgr = new GlideRecord(tableName);
        if (cgr.get(input.sys_id)) {
            cgr.work_notes = input.comment;
            cgr.update();
            data.updateResult = { success: true, message: 'Work note added.' };
        }
    }

    // Read record: support record_id, sys_id, and number
    var recordId = $sp.getParameter('record_id') || $sp.getParameter('sys_id') || (input && input.sys_id) || '';
    var recordNumber = $sp.getParameter('number') || '';

    if (!recordId && !recordNumber) {
        data.error = 'No record specified. Please provide a record ID.';
        return;
    }

    var STATUS_CLASS = {
        'new': 'label-info',
        'assigned': 'label-warning',
        'in_progress': 'label-primary',
        'pending': 'label-default',
        'resolved': 'label-success',
        'closed': 'label-default'
    };

    var PRIORITY_CLASS = {
        'p1_critical': 'label-danger',
        'p2_high': 'label-warning',
        'p3_medium': 'label-info',
        'p4_low': 'label-success'
    };

    var SEVERITY_CLASS = {
        'critical': 'label-danger',
        'high': 'label-warning',
        'medium': 'label-info',
        'low': 'label-success'
    };

    var gr = new GlideRecord(tableName);
    var found = false;
    if (recordId) {
        found = gr.get(recordId);
    } else if (recordNumber) {
        gr.addQuery('number', recordNumber);
        gr.query();
        found = gr.next();
    }

    if (found) {
        var rawConf = (gr.getValue('ai_confidence') || '').replace(/%+$/, '').trim();

        data.record = {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') || '',
            short_description: gr.getValue('short_description') || '',
            description: gr.getValue('description') || '',
            exception_type: gr.getDisplayValue('exception_type') || gr.getValue('exception_type') || '',
            exception_type_val: gr.getValue('exception_type') || '',
            location: gr.getValue('location') || '',
            severity: gr.getDisplayValue('severity') || gr.getValue('severity') || '',
            severity_val: gr.getValue('severity') || '',
            severityClass: SEVERITY_CLASS[gr.getValue('severity')] || 'label-default',
            priority: gr.getDisplayValue('priority') || gr.getValue('priority') || '',
            priority_val: gr.getValue('priority') || '',
            priorityClass: PRIORITY_CLASS[gr.getValue('priority')] || 'label-default',
            status: gr.getDisplayValue('status') || gr.getValue('status') || '',
            status_val: gr.getValue('status') || '',
            statusClass: STATUS_CLASS[gr.getValue('status')] || 'label-default',
            reported_by: gr.getDisplayValue('reported_by') || 'Warehouse Staff',
            assigned_to: gr.getDisplayValue('assigned_to') || '',
            assigned_to_id: gr.getValue('assigned_to') || '',
            assignment_group: gr.getDisplayValue('assignment_group') || '',
            resolution_notes: gr.getValue('resolution_notes') || '',
            resolved_at: gr.getDisplayValue('resolved_at') || '',
            created: gr.getDisplayValue('sys_created_on') || '',
            updated: gr.getDisplayValue('sys_updated_on') || '',
            ai_suggested_type: gr.getDisplayValue('ai_suggested_type') || gr.getValue('ai_suggested_type') || '',
            ai_suggested_severity: gr.getDisplayValue('ai_suggested_severity') || gr.getValue('ai_suggested_severity') || '',
            ai_confidence: rawConf ? (rawConf + '%') : '',
            ai_reason: gr.getValue('ai_reason') || '',
            ai_routing_suggestion: gr.getValue('ai_routing_suggestion') || '',
            ai_insights: gr.getValue('ai_insights') || ''
        };

        data.hasAI = !!(data.record.ai_suggested_type || data.record.ai_suggested_severity || data.record.ai_insights || data.record.ai_routing_suggestion);

        // Technician status transitions
        if (data.isTechnician) {
            var currentStatus = gr.getValue('status');
            if (currentStatus === 'assigned') {
                data.statusOptions = [{ value: 'in_progress', label: 'In Progress' }];
            } else if (currentStatus === 'in_progress') {
                data.statusOptions = [{ value: 'resolved', label: 'Resolved' }];
            }
        }

        // Supervisor can set any forward status
        if (data.isSupervisor) {
            data.statusOptions = [
                { value: 'new', label: 'New' },
                { value: 'assigned', label: 'Assigned' },
                { value: 'in_progress', label: 'In Progress' },
                { value: 'pending', label: 'Pending' },
                { value: 'resolved', label: 'Resolved' },
                { value: 'closed', label: 'Closed' }
            ];
        }
    } else {
        data.error = 'Exception record not found.';
        return;
    }

    // Load technicians for supervisor assignment
    if (data.canAssign) {
        data.technicians = [];
        try {
            var userGr = new GlideRecord('sys_user_has_role');
            userGr.addQuery('role.name', 'x_1956908_wareho_0.technician');
            userGr.addQuery('user.active', true);
            userGr.setLimit(50);
            userGr.query();
            while (userGr.next()) {
                data.technicians.push({
                    sys_id: userGr.getValue('user'),
                    name: userGr.getDisplayValue('user')
                });
            }
        } catch(e) {}
    }

    // Load work notes / comments
    data.comments = [];
    try {
        var jGr = new GlideRecord('sys_journal_field');
        jGr.addQuery('element_id', data.record.sys_id);
        jGr.addQuery('name', tableName);
        jGr.addQuery('element', 'work_notes');
        jGr.orderByDesc('sys_created_on');
        jGr.setLimit(20);
        jGr.query();
        while (jGr.next()) {
            data.comments.push({
                sys_id: jGr.getUniqueValue(),
                value: jGr.getValue('value') || '',
                created: jGr.getDisplayValue('sys_created_on'),
                created_by: jGr.getDisplayValue('sys_created_by')
            });
        }
    } catch(e) {}
})();
